SELECT analytics_expense_facts.expense_category, SUM(analytics_expense_facts.expense_amount) AS expense_amount FROM analytics_expense_facts WHERE analytics_expense_facts.year = 2025 AND analytics_expense_facts.month = 11 AND analytics_expense_facts.department = 'department_09' AND analytics_expense_facts.cost_center = 'cc_054' GROUP BY analytics_expense_facts.expense_category ORDER BY expense_amount DESC, analytics_expense_facts.expense_category ASC LIMIT 15
